package org.apache.commons.cli;

import org.junit.Test;

import java.util.ArrayList;
import java.util.Collection;

import static org.junit.Assert.*;

public class AddOptionsTests {

    @Test
    public void testAddOptionsAddsAllOptionsAndOptionGroups() {
        Options target = new Options();
        Options source = new Options();

        Option alpha = Option.builder("a").longOpt("alpha").desc("alpha").build();
        Option beta = Option.builder("b").longOpt("beta").desc("beta").build();
        source.addOption(alpha);
        source.addOption(beta);

        OptionGroup group = new OptionGroup();
        group.addOption(Option.builder("x").desc("x").build());
        group.addOption(Option.builder("y").desc("y").build());
        source.addOptionGroup(group);

        Options returned = target.addOptions(source);

        assertSame(target, returned);
        assertTrue(target.hasOption("a"));
        assertTrue(target.hasOption("b"));
        assertEquals(2, target.getOptions().size());

        Collection<OptionGroup> optionGroups = target.getOptionGroups();
        assertEquals(1, optionGroups.size());
        assertTrue(new ArrayList<>(optionGroups).contains(group));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAddOptionsThrowsOnDuplicateNonNullKey() {
        Options target = new Options();
        target.addOption(Option.builder("a").desc("existing").build());

        Options source = new Options();
        source.addOption(Option.builder("a").desc("duplicate").build());

        target.addOptions(source);
    }

    @Test
    public void testAddOptionsAllowsMultipleNullKeyOptions() {
        Options target = new Options();
        Options source = new Options();

        Option unnamedOne = new Option(null, "first");
        Option unnamedTwo = new Option(null, "second");
        source.addOption(unnamedOne);
        source.addOption(unnamedTwo);

        Options returned = target.addOptions(source);

        assertSame(target, returned);
        assertEquals(2, target.getOptions().size());
        assertFalse(target.hasOption(null));
        assertTrue(target.getOptions().contains(unnamedOne));
        assertTrue(target.getOptions().contains(unnamedTwo));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAddOptionsStillThrowsWhenDuplicateExistsAndSourceContainsNullKeyOptionFirst() {
        Options target = new Options();
        target.addOption(Option.builder("a").desc("existing").build());

        Options source = new Options();
        source.addOption(new Option(null, "unnamed"));
        source.addOption(Option.builder("a").desc("duplicate").build());

        target.addOptions(source);
    }
}

