package org.apache.commons.cli;

import static org.junit.Assert.*;

import java.util.Arrays;
import java.util.Collection;
import java.util.Iterator;

import org.junit.Test;

public class AddRequiredOptionTests {

    @Test
    public void testAddRequiredOptionWithArgumentOption() {
        Options options = new Options();

        Options returned = options.addRequiredOption("f", "file", true, "file name");

        assertSame(options, returned);
        assertTrue(options.hasOption("f"));
        assertTrue(options.hasLongOption("file"));

        Option option = options.getOption("f");
        assertNotNull(option);
        assertEquals("f", option.getOpt());
        assertEquals("file", option.getLongOpt());
        assertTrue(option.hasArg());
        assertTrue(option.isRequired());
        assertEquals("file name", option.getDescription());
    }

    @Test
    public void testAddRequiredOptionWithNoArgumentOption() {
        Options options = new Options();

        options.addRequiredOption("v", "verbose", false, "verbose mode");

        Option option = options.getOption("v");
        assertNotNull(option);
        assertEquals("v", option.getOpt());
        assertEquals("verbose", option.getLongOpt());
        assertFalse(option.hasArg());
        assertTrue(option.isRequired());
        assertEquals("verbose mode", option.getDescription());
    }

    @Test
    public void testAddRequiredOptionDoesNotInvertHasArgForBothCases() {
        Options options = new Options();

        options.addRequiredOption("a", "alpha", true, "requires argument");
        options.addRequiredOption("b", "beta", false, "no argument");

        Option argOption = options.getOption("a");
        Option noArgOption = options.getOption("b");

        assertNotNull(argOption);
        assertNotNull(noArgOption);

        assertTrue(argOption.hasArg());
        assertFalse(noArgOption.hasArg());
    }

    @Test
    public void testAddRequiredOptionAddsToRequiredOptionsCollection() {
        Options options = new Options();

        options.addRequiredOption("c", "config", true, "configuration");

        Collection<?> required = options.getRequiredOptions();
        assertNotNull(required);
        assertEquals(1, required.size());

        Object first = required.iterator().next();
        assertEquals("c", first);
        assertTrue(required.contains("c"));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAddRequiredOptionRejectsNullOpt() {
        Options options = new Options();
        options.addRequiredOption(null, "nullOpt", true, "desc");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAddRequiredOptionRejectsEmptyOpt() {
        Options options = new Options();
        options.addRequiredOption("", "emptyOpt", true, "desc");
    }

    @Test
    public void testAddRequiredOptionCanBeChainedAndAllOptionsRemainAccessible() {
        Options options = new Options();

        Options returned = options.addRequiredOption("x", "xray", true, "x arg")
                                 .addRequiredOption("y", "yankee", false, "y no arg");

        assertSame(options, returned);
        assertTrue(options.hasOption("x"));
        assertTrue(options.hasOption("y"));

        Option x = options.getOption("x");
        Option y = options.getOption("y");

        assertNotNull(x);
        assertNotNull(y);
        assertTrue(x.hasArg());
        assertFalse(y.hasArg());
        assertTrue(x.isRequired());
        assertTrue(y.isRequired());
    }
}

