package org.apache.commons.cli.help;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

import org.junit.Test;

public class PadTests {

    @Test
    public void testPadLeftUnsetMaxWidthAddIndentFalseEmptyTextAddsSingleSpaceForMutant() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.LEFT)
                .setIndent(3)
                .get();

        CharSequence result = style.pad(false, "");

        assertEquals("", result.toString());
    }

    @Test
    public void testPadLeftUnsetMaxWidthAddIndentTrueEmptyTextAddsIndentOnly() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.LEFT)
                .setIndent(3)
                .get();

        CharSequence result = style.pad(true, "");

        assertEquals("   ", result.toString());
    }

    @Test
    public void testPadRightUnsetMaxWidthAddIndentFalseEmptyTextAddsSingleSpaceForMutant() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.RIGHT)
                .setIndent(3)
                .get();

        CharSequence result = style.pad(false, "");

        assertEquals("", result.toString());
    }

    @Test
    public void testPadRightUnsetMaxWidthAddIndentTrueEmptyTextAddsIndentOnly() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.RIGHT)
                .setIndent(3)
                .get();

        CharSequence result = style.pad(true, "");

        assertEquals("   ", result.toString());
    }

    @Test
    public void testPadLeftUnsetMaxWidthNonEmptyTextNoIndent() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.LEFT)
                .setIndent(4)
                .get();

        CharSequence result = style.pad(false, "abc");

        assertEquals("abc", result.toString());
    }

    @Test
    public void testPadReturnsSameTextWhenLengthMeetsMaxWidth() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.LEFT)
                .setMaxWidth(3)
                .setIndent(4)
                .get();

        CharSequence input = new StringBuilder("abc");
        CharSequence result = style.pad(true, input);

        assertSame(input, result);
    }
}

