package org.apache.commons.cli.help;

import org.junit.Test;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.Collections;

import static org.junit.Assert.assertEquals;

public class AdjustTableFormatTests {

    private Object invokeAdjustTableFormat(TextHelpAppendable appendable, Object table) throws Exception {
        Method method = TextHelpAppendable.class.getDeclaredMethod("adjustTableFormat", table.getClass());
        method.setAccessible(true);
        try {
            return method.invoke(appendable, table);
        } catch (InvocationTargetException e) {
            if (e.getCause() instanceof Exception) {
                throw (Exception) e.getCause();
            }
            throw e;
        }
    }

    private TextHelpAppendable.Style buildStyle(int maxWidth, int leftPad, int indent, boolean scalable) {
        TextHelpAppendable.Style.Builder builder = TextHelpAppendable.Style.builder()
                .setMaxWidth(maxWidth)
                .setLeftPad(leftPad)
                .setIndent(indent);
        if (!scalable) {
            builder.setScalable(false);
        }
        return builder.get();
    }

    @Test
    public void adjustsUnsetMaxWidthToHeaderLength() throws Exception {
        TextHelpAppendable appendable = new TextHelpAppendable(new StringBuilder());

        TextHelpAppendable.Style style = buildStyle(
                TextHelpAppendable.Style.UNSET_MAX_WIDTH,
                1,
                0,
                true
        );

        TextHelpAppendable.TableDefinition table = TextHelpAppendable.TableDefinition.from(
                "caption",
                Collections.singletonList(style),
                Collections.singletonList("HEADER"),
                Collections.singletonList(Collections.singletonList("abc"))
        );

        TextHelpAppendable.TableDefinition adjusted =
                (TextHelpAppendable.TableDefinition) invokeAdjustTableFormat(appendable, table);

        assertEquals(6, adjusted.columnTextStyles().get(0).getMaxWidth());
        assertEquals(6, adjusted.columnTextStyles().get(0).getMinWidth());
    }

    @Test
    public void doesNotReduceExplicitMaxWidthWhenHeaderIsLongerAndCellFits() throws Exception {
        TextHelpAppendable appendable = new TextHelpAppendable(new StringBuilder());

        TextHelpAppendable.Style style = buildStyle(10, 1, 0, true);

        TextHelpAppendable.TableDefinition table = TextHelpAppendable.TableDefinition.from(
                "caption",
                Collections.singletonList(style),
                Collections.singletonList("12345678901"),
                Collections.singletonList(Collections.singletonList("abc"))
        );

        TextHelpAppendable.TableDefinition adjusted =
                (TextHelpAppendable.TableDefinition) invokeAdjustTableFormat(appendable, table);

        assertEquals(10, adjusted.columnTextStyles().get(0).getMaxWidth());
        assertEquals(11, adjusted.columnTextStyles().get(0).getMinWidth());
    }

    @Test
    public void expandsMaxWidthToLargestCell() throws Exception {
        TextHelpAppendable appendable = new TextHelpAppendable(new StringBuilder());

        TextHelpAppendable.Style style = buildStyle(4, 1, 0, true);

        TextHelpAppendable.TableDefinition table = TextHelpAppendable.TableDefinition.from(
                "caption",
                Collections.singletonList(style),
                Collections.singletonList("ab"),
                Arrays.asList(
                        Collections.singletonList("abc"),
                        Collections.singletonList("abcdef")
                )
        );

        TextHelpAppendable.TableDefinition adjusted =
                (TextHelpAppendable.TableDefinition) invokeAdjustTableFormat(appendable, table);

        assertEquals(6, adjusted.columnTextStyles().get(0).getMaxWidth());
    }

    @Test
    public void preservesNonScalableColumnWidthWhenRescalingIsNeeded() throws Exception {
        TextHelpAppendable appendable = new TextHelpAppendable(new StringBuilder());

        TextHelpAppendable.Style nonScalableStyle = buildStyle(10, 1, 0, false);
        TextHelpAppendable.Style scalableStyle = buildStyle(80, 1, 0, true);

        TextHelpAppendable.TableDefinition table = TextHelpAppendable.TableDefinition.from(
                "caption",
                Arrays.asList(nonScalableStyle, scalableStyle),
                Arrays.asList("A", "B"),
                Arrays.asList(
                        Arrays.asList("1234567890", "12345678901234567890123456789012345678901234567890")
                )
        );

        TextHelpAppendable.TableDefinition adjusted =
                (TextHelpAppendable.TableDefinition) invokeAdjustTableFormat(appendable, table);

        assertEquals(10, adjusted.columnTextStyles().get(0).getMaxWidth());
        assertEquals(19, adjusted.columnTextStyles().get(1).getMaxWidth());
    }

    @Test
    public void resizesScalableColumnsWhenTotalWidthExceedsAvailableWidth() throws Exception {
        TextHelpAppendable appendable = new TextHelpAppendable(new StringBuilder());

        TextHelpAppendable.Style style1 = buildStyle(50, 1, 0, true);
        TextHelpAppendable.Style style2 = buildStyle(50, 1, 0, true);

