        ExposedTextHelpAppendable appendable = new ExposedTextHelpAppendable();

        appendable.callMakeColumnQueue("abc", null);
    }

    @Test
    public void testReturnedQueueContainsAllWrappedPartsInOrder() {
        ExposedTextHelpAppendable appendable = new ExposedTextHelpAppendable();
        TextStyle textStyle = style(8, 1, 1);

        Queue<String> result = appendable.callMakeColumnQueue("one two three", textStyle);

        assertEquals(3, result.size());
        assertEquals(" one", result.poll());
        assertEquals(" two", result.poll());
        assertEquals("  three", result.poll());
