package org.apache.commons.cli.help;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

public class IndexOfWrapTests {

    @Test
    public void testThrowsOnZeroWidth() {
        try {
            TextHelpAppendable.indexOfWrap("abc", 0, 0);
        } catch (IllegalArgumentException ex) {
            assertEquals("Width must be greater than 0", ex.getMessage());
            return;
        }
        throw new AssertionError("Expected IllegalArgumentException");
    }

    @Test
    public void testReturnsBreakCharWithinWrapRange() {
        assertEquals(1, TextHelpAppendable.indexOfWrap("a\nbc", 10, 0));
    }

    @Test
    public void testReturnsTextLengthWhenWrapExceedsRemainingText() {
        assertEquals(3, TextHelpAppendable.indexOfWrap("abc", 10, 0));
    }

    @Test
    public void testReturnsLastWhitespaceBeforeLimitWhenNoBreakChar() {
        assertEquals(3, TextHelpAppendable.indexOfWrap("abc defgh", 4, 0));
    }

    @Test
    public void testReturnsLimitMinusOneWhenNoWhitespaceOrBreakChar() {
        assertEquals(3, TextHelpAppendable.indexOfWrap("abcdef", 4, 0));
    }

    @Test
    public void testUsesStartPositionAndFindsBreakCharAfterIt() {
        assertEquals(5, TextHelpAppendable.indexOfWrap("abcde\nxyz", 4, 2));
    }

    @Test
    public void testReturnsTextLengthWhenStartNearEndAndWidthCoversRemainingText() {
        assertEquals(6, TextHelpAppendable.indexOfWrap("abcdef", 2, 4));
    }
}

