package org.apache.commons.cli;

import static org.junit.Assert.*;

import org.junit.Test;

public class AddOptionGroupTests {

    @Test
    public void testAddRequiredOptionGroupAddsGroupBeforeOptions() {
        Options options = new Options();
        OptionGroup group = new OptionGroup();
        Option opt = new Option("a", "alpha");
        group.addOption(opt);
        group.setRequired(true);

        Options returned = options.addOptionGroup(group);

        assertSame(options, returned);
        assertFalse(opt.isRequired());
        assertTrue(options.hasOption("a"));
        assertSame(group, options.getOptionGroup(opt));
        assertTrue(options.getRequiredOptions().contains(group));
        assertTrue(options.getOptionGroup(opt).isRequired());
    }

    @Test
    public void testAddNonRequiredOptionGroupDoesNotAddGroupToRequiredOptions() {
        Options options = new Options();
        OptionGroup group = new OptionGroup();
        Option opt = new Option("b", "beta");
        group.addOption(opt);
        group.setRequired(false);

        options.addOptionGroup(group);

        assertFalse(opt.isRequired());
        assertTrue(options.hasOption("b"));
        assertSame(group, options.getOptionGroup(opt));
        assertFalse(options.getRequiredOptions().contains(group));
    }

    @Test
    public void testAddRequiredOptionGroupWithNullKeyOptionDoesNotMutateRequiredOptionsWithNull() {
        Options options = new Options();
        OptionGroup group = new OptionGroup();
        Option opt = new Option((String) null, "no-arg");
        group.addOption(opt);
        group.setRequired(true);

        options.addOptionGroup(group);

        assertFalse(opt.isRequired());
        assertTrue(options.getRequiredOptions().contains(group));
        assertSame(group, options.getOptionGroup(opt));
        assertTrue(options.hasOption("no-arg"));
    }

    @Test
    public void testAddOptionGroupRemovesExistingRequiredOptionByKey() {
        Options options = new Options();
        options.addRequiredOption("c", "charlie", false, null);

        OptionGroup group = new OptionGroup();
        Option opt = new Option("c", "charlie");
        group.addOption(opt);
        group.setRequired(false);

        options.addOptionGroup(group);

        assertFalse(opt.isRequired());
        assertFalse(options.getRequiredOptions().contains("c"));
        assertTrue(options.hasOption("c"));
        assertSame(group, options.getOptionGroup(opt));
    }

    @Test
    public void testAddOptionGroupNullThrowsNullPointerException() {
        Options options = new Options();

        try {
            options.addOptionGroup(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException expected) {
            assertNotNull(expected);
        }
    }
}

package org.apache.commons.cli;

import static org.junit.Assert.*;

import java.util.Collection;

import org.junit.Test;

public class AddOptionGroupTests {

    @Test
    public void testAddOptionGroupWithRequiredGroupMarksGroupRequiredAndRegistersOptions() {
        Options options = new Options();

        OptionGroup group = new OptionGroup();
        group.setRequired(true);

        Option optA = new Option("a", "alpha");
        optA.setRequired(true);
        Option optB = new Option("b", "beta");
        optB.setRequired(true);

        group.addOption(optA);
        group.addOption(optB);

        Options returned = options.addOptionGroup(group);

        assertSame(options, returned);
        assertFalse(optA.isRequired());
        assertFalse(optB.isRequired());

        Collection<?> required = options.getRequiredOptions();
        assertTrue(required.contains(group));
        assertFalse(required.contains("a"));
        assertFalse(required.contains("b"));

        assertSame(group, options.getOptionGroup(optA));
        assertSame(group, options.getOptionGroup(optB));

        assertEquals(optA, options.getOption("a"));
        assertEquals(optB, options.getOption("b"));
    }

    @Test
    public void testAddOptionGroupWithNonRequiredGroupDoesNotAddGroupToRequiredOptions() {
        Options options = new Options();

        OptionGroup group = new OptionGroup();
        group.setRequired(false);

        Option optA = new Option("a", "alpha");
        group.addOption(optA);

        options.addOptionGroup(group);

        Collection<?> required = options.getRequiredOptions();
        assertFalse(required.contains(group));
        assertFalse(required.contains("a"));
        assertSame(group, options.getOptionGroup(optA));
        assertEquals(optA, options.getOption("a"));
    }

    @Test
    public void testAddOptionGroupRemovesExistingRequiredKeyFromRequiredOptions() {
        Options options = new Options();

        options.addRequiredOption("a", "alpha", true, "desc");

        Collection<?> before = options.getRequiredOptions();
        assertTrue(before.contains("a"));

        OptionGroup group = new OptionGroup();
        group.setRequired(false);
        Option optA = new Option("a", "alpha");
        group.addOption(optA);

        options.addOptionGroup(group);

        Collection<?> after = options.getRequiredOptions();
        assertFalse(after.contains("a"));
        assertSame(group, options.getOptionGroup(optA));
        assertEquals(optA, options.getOption("a"));
    }

    @Test
    public void testAddOptionGroupDoesNotRemoveOtherRequiredOptions() {
        Options options = new Options();

        options.addRequiredOption("x", "xray", true, "desc");
        options.addRequiredOption("y", "yankee", true, "desc");

        OptionGroup group = new OptionGroup();
        group.setRequired(false);
        Option optA = new Option("a", "alpha");
        group.addOption(optA);

        options.addOptionGroup(group);

        Collection<?> required = options.getRequiredOptions();
        assertTrue(required.contains("x"));
        assertTrue(required.contains("y"));
        assertFalse(required.contains("a"));
    }

    @Test
    public void testAddOptionGroupWithEmptyGroupStillReturnsThisAndDoesNotThrow() {
        Options options = new Options();

        OptionGroup group = new OptionGroup();
        group.setRequired(true);

        Options returned = options.addOptionGroup(group);

        assertSame(options, returned);
        Collection<?> required = options.getRequiredOptions();
        assertTrue(required.contains(group));
        assertTrue(options.getOptions().isEmpty());
    }
}

